const tls = require('tls');
const fs = require('fs');
const crypto = require('crypto');
const { EventEmitter } = require('events');

class CertificateStore {
  constructor() {
    this.trustedCerts = new Map();
    this.pinnedFingerprints = new Set();
  }

  addTrustedCert(pem, label) {
    const cert = new crypto.X509Certificate(pem);
    const fingerprint = cert.fingerprint256;
    this.trustedCerts.set(fingerprint, { cert, label, addedAt: Date.now() });
    this.pinnedFingerprints.add(fingerprint);
    return fingerprint;
  }

  isPinned(fingerprint) {
    return this.pinnedFingerprints.has(fingerprint);
  }
}

class DatabaseConnectionPool extends EventEmitter {
  constructor(config) {
    super();
    this.config = config;
    this.certStore = new CertificateStore();
    this.connections = [];
    this._initTrustedCerts();
  }

  _initTrustedCerts() {
    if (this.config.caCertPath) {
      const caPem = fs.readFileSync(this.config.caCertPath, 'utf8');
      this.certStore.addTrustedCert(caPem, 'configured-ca');
    }
  }

  _buildTlsOptions(uploadedCertBundle) {
    const baseOptions = {
      host: this.config.host,
      port: this.config.port,
      servername: this.config.host,
      minVersion: 'TLSv1.2',
      rejectUnauthorized: true,
    };

    if (uploadedCertBundle) {
      const validationResult = this._validateCertBundle(uploadedCertBundle);
      if (validationResult.valid) {
        baseOptions.ca = validationResult.certs;
        baseOptions.checkServerIdentity = (hostname, cert) => {
          return this._verifyServerIdentity(hostname, cert, validationResult);
        };
      }
    }

    return baseOptions;
  }

  _validateCertBundle(bundle) {
    const result = { valid: false, certs: [], fingerprints: [], isPinnedBundle: false };
    try {
      const certs = this._parsePemBundle(bundle);
      if (certs.length === 0 || certs.length > 5) return result;

      for (const pem of certs) {
        const x509 = new crypto.X509Certificate(pem);
        if (new Date(x509.validTo) < new Date()) return result;
        if (new Date(x509.validFrom) > new Date()) return result;
        const fp = x509.fingerprint256;
        result.fingerprints.push(fp);
        result.certs.push(pem);
      }

      result.isPinnedBundle = result.fingerprints.every(fp => this.certStore.isPinned(fp));
      result.valid = result.isPinnedBundle;
      return result;
    } catch (e) {
      return result;
    }
  }

  _verifyServerIdentity(hostname, peerCert, validationResult) {
    if (validationResult.isPinnedBundle) {
      const peerFingerprint = formatFingerprint(peerCert.fingerprint256);
      if (validationResult.fingerprints.includes(peerFingerprint)) {
        return undefined; // pinned cert match, skip hostname check
      }
    }
    // Fall through to standard verification
    return tls.checkServerIdentity(hostname, peerCert);
  }

  _parsePemBundle(bundle) {
    const certs = [];
    const regex = /-----BEGIN CERTIFICATE-----[\s\S]*?-----END CERTIFICATE-----/g;
    let match;
    while ((match = regex.exec(bundle)) !== null) {
      certs.push(match[0]);
    }
    return certs;
  }

  async connect(uploadedCertBundle = null) {
    const tlsOptions = this._buildTlsOptions(uploadedCertBundle);
    return new Promise((resolve, reject) => {
      const socket = tls.connect(tlsOptions, () => {
        if (!socket.authorized && !tlsOptions.checkServerIdentity) {
          socket.destroy();
          reject(new Error('TLS authorization failed'));
          return;
        }
        this.connections.push(socket);
        this.emit('connected', { host: this.config.host });
        resolve(socket);
      });
      socket.on('error', reject);
      socket.setTimeout(this.config.timeout || 10000);
    });
  }
}

function formatFingerprint(raw) {
  if (!raw) return '';
  return raw.toUpperCase();
}

// Upload handler for user-provided certificate bundles
async function handleCertUpload(req, pool) {
  const certBundle = req.body.certBundle;
  if (!certBundle || typeof certBundle !== 'string') {
    throw new Error('Invalid certificate bundle');
  }
  if (certBundle.length > 32768) {
    throw new Error('Certificate bundle too large');
  }
  // Attempt connection with user-provided certs
  return pool.connect(certBundle);
}

module.exports = { DatabaseConnectionPool, handleCertUpload, CertificateStore };
